// graph_engine.cpp -- 3-stage pipelined batch engine for graph "tree"
// AUTO-GENERATED by gen_hls_pipelined.py. Do not edit by hand.
//
// One hop per stage, 3 stages, HLS-pipelined at II=1 over the batch:
// latency 3 clocks, throughput one query per clock.
#include "graph_wire.hpp"

extern "C" void graph_engine_batch(
        const gw_word_t *seed_in,
        gw_word_t       *state_out,
        unsigned        *count_out,
        unsigned         nq,
        unsigned         num_steps) {
#pragma HLS INTERFACE m_axi     port=seed_in   bundle=gmem0 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=state_out bundle=gmem1 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=count_out bundle=gmem2 offset=slave depth=1024
#pragma HLS INTERFACE s_axilite port=seed_in   bundle=control
#pragma HLS INTERFACE s_axilite port=state_out bundle=control
#pragma HLS INTERFACE s_axilite port=count_out bundle=control
#pragma HLS INTERFACE s_axilite port=nq        bundle=control
#pragma HLS INTERFACE s_axilite port=num_steps bundle=control
#pragma HLS INTERFACE s_axilite port=return    bundle=control

    const unsigned ksel = (num_steps > GW_STAGES) ? GW_STAGES : num_steps;

    // One iteration per query. II=1 -> a new query enters every clock;
    // the 3 hop stages below become the pipeline depth.
    BATCH: for (unsigned q = 0; q < nq; ++q) {
#pragma HLS PIPELINE II=1
        ap_uint<1> s0[GW_N];
#pragma HLS ARRAY_PARTITION variable=s0 complete dim=1
        LOADQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = seed_in[q * GW_NW + w];
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) s0[idx] = word[b];
            }
        }

        ap_uint<1> st[GW_STAGES + 1][GW_N];
#pragma HLS ARRAY_PARTITION variable=st complete dim=0
        COPY0: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            st[0][v] = s0[v];
        }

        // ===== baked wiring, one hop per stage =====
        // ---- stage 1 ----
        st[1][0] = st[0][0];
        st[1][1] = st[0][1] | st[0][0];
        st[1][2] = st[0][2] | st[0][0];
        st[1][3] = st[0][3] | st[0][1];
        st[1][4] = st[0][4] | st[0][1];
        st[1][5] = st[0][5] | st[0][2];
        st[1][6] = st[0][6] | st[0][2];
        st[1][7] = st[0][7] | st[0][3];
        st[1][8] = st[0][8] | st[0][3];
        st[1][9] = st[0][9] | st[0][4];
        st[1][10] = st[0][10] | st[0][4];
        // ---- stage 2 ----
        st[2][0] = st[1][0];
        st[2][1] = st[1][1] | st[1][0];
        st[2][2] = st[1][2] | st[1][0];
        st[2][3] = st[1][3] | st[1][1];
        st[2][4] = st[1][4] | st[1][1];
        st[2][5] = st[1][5] | st[1][2];
        st[2][6] = st[1][6] | st[1][2];
        st[2][7] = st[1][7] | st[1][3];
        st[2][8] = st[1][8] | st[1][3];
        st[2][9] = st[1][9] | st[1][4];
        st[2][10] = st[1][10] | st[1][4];
        // ---- stage 3 ----
        st[3][0] = st[2][0];
        st[3][1] = st[2][1] | st[2][0];
        st[3][2] = st[2][2] | st[2][0];
        st[3][3] = st[2][3] | st[2][1];
        st[3][4] = st[2][4] | st[2][1];
        st[3][5] = st[2][5] | st[2][2];
        st[3][6] = st[2][6] | st[2][2];
        st[3][7] = st[2][7] | st[2][3];
        st[3][8] = st[2][8] | st[2][3];
        st[3][9] = st[2][9] | st[2][4];
        st[3][10] = st[2][10] | st[2][4];
        // ===== end baked wiring =====

        // Select the requested depth (constant-indexed mux, not a loop).
        ap_uint<1> res[GW_N];
#pragma HLS ARRAY_PARTITION variable=res complete dim=1
        SEL: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            res[v] = st[ksel][v];
        }

        unsigned c = 0;
        CNT: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            c += (unsigned) res[v];
        }
        count_out[q] = c;

        STOREQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = 0;
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) word[b] = res[idx];
            }
            state_out[q * GW_NW + w] = word;
        }
    }
}
